(663570, 69556, 8643, '<td valign="top">I love this - captures the spirit of the challenge, great composition and works especially well in black and white.  Easily the best of the bunch!</td>', 'I love this - captures the spirit of the challenge, great composition and works especially well in black and white.  Easily the best of the bunch!', '2004-04-12 08:24:00.000000', NULL, 1),
(663593, 69525, 15920, '<td valign="top">I''m guessing that the time of year (late winter/early spring) made B&amp;W the right choice for this shot with no leaves on the tress, no green to be found.  So, take this for what it is worth: I am left thinking that this would have been stronger in color.  Given the B&amp;W choice, a little extra contrast would have helped on the house to the left. All that aside, the beveled glass was a great choice for the challenge. -6</td>', 'I''m guessing that the time of year (late winter/early spring) made B&W the right choice for this shot with no leaves on the tress, no green to be found.  So, take this for what it is worth: I am left thinking that this would have been stronger in color.  Given the B&W choice, a little extra contrast would have helped on the house to the left. All that aside, the beveled glass was a great choice for the challenge. -6', '2004-04-12 09:02:40.000000', NULL, 1),
(663600, 69506, 5792, '<td valign="top">Wonderful sunset for a great window shot. You should have cropped that distracting few pixels at the top of the image of this otherwise terrific shot.</td>', 'Wonderful sunset for a great window shot. You should have cropped that distracting few pixels at the top of the image of this otherwise terrific shot.', '2004-04-12 09:09:33.000000', NULL, 1),
(663601, 69132, 15920, '<td valign="top">There are a few artifacts, and I wonder why this isn''t color, but this is great composition. -7</td>', 'There are a few artifacts, and I wonder why this isn''t color, but this is great composition. -7', '2004-04-12 09:09:34.000000', NULL, 1),
(663603, 68820, 15920, '<td valign="top">Not sure I can make out the window.</td>', 'Not sure I can make out the window.', '2004-04-12 09:10:59.000000', NULL, 1),
(663607, 69141, 15920, '<td valign="top">I thought about a similar crop, and though I couldn''t you made it work pretty well.  The colors are a bit flat, otherwise, this would have been stronger. -5</td>', 'I thought about a similar crop, and though I couldn''t you made it work pretty well.  The colors are a bit flat, otherwise, this would have been stronger. -5', '2004-04-12 09:13:40.000000', NULL, 1),
(663615, 69671, 5792, '<td valign="top">Good quality and give the viewer the feeling of being there. The clock off by 12 hours is a little distracting. :)</td>', 'Good quality and give the viewer the feeling of being there. The clock off by 12 hours is a little distracting. :)', '2004-04-12 09:17:49.000000', NULL, 1),
(663624, 68624, 15920, '<td valign="top">I don''t think I can really see through the window, but, so what?  I like this picture for the detail, and the colors. A polarizer and a view through the window would have gotten a slightly higher score. -7</td>', 'I don''t think I can really see through the window, but, so what?  I like this picture for the detail, and the colors. A polarizer and a view through the window would have gotten a slightly higher score. -7', '2004-04-12 09:34:17.000000', NULL, 1),
