(663712, 69037, 5391, '<td valign="top">Nice concept - this could be used on a church bulletin of some sort.  I find the high contrast (especially the blown-out whites) and the unusual border a bit disturbing, however.</td>', 'Nice concept - this could be used on a church bulletin of some sort.  I find the high contrast (especially the blown-out whites) and the unusual border a bit disturbing, however.', '2004-04-12 11:55:34.000000', NULL, 1),
(663714, 69028, 5391, '<td valign="top">This is an interesting composition, but I think that the cut off flagpole really detracts from the geometrical similarity you get between the triangle window frame and the triangle mountain shape echoing it in the background.</td>', 'This is an interesting composition, but I think that the cut off flagpole really detracts from the geometrical similarity you get between the triangle window frame and the triangle mountain shape echoing it in the background.', '2004-04-12 11:57:33.000000', NULL, 1),
(663716, 68983, 5391, '<td valign="top">Lovely shot, but unfortunately, I think that the window being in the background seems rather incidental - it would be as good of a shot (if not better) without it, so I don''t think it fits with the challenge theme very well.</td>', 'Lovely shot, but unfortunately, I think that the window being in the background seems rather incidental - it would be as good of a shot (if not better) without it, so I don''t think it fits with the challenge theme very well.', '2004-04-12 11:58:57.000000', NULL, 1),
(663718, 69439, 5391, '<td valign="top">The lightning is impressive, but I think that the window frame and the reflections really detract from this image, and the idea of the challenge was to try and inspire people to use the windows in a creative way - here it just seems incidental and would probably be better without it, actually.</td>', 'The lightning is impressive, but I think that the window frame and the reflections really detract from this image, and the idea of the challenge was to try and inspire people to use the windows in a creative way - here it just seems incidental and would probably be better without it, actually.', '2004-04-12 12:01:22.000000', NULL, 1),
(663720, 69094, 5391, '<td valign="top">Lovely, beautiful!  Great use of the window to frame the subject and quite a lovely view!  8</td>', 'Lovely, beautiful!  Great use of the window to frame the subject and quite a lovely view!  8', '2004-04-12 12:01:55.000000', NULL, 1),
