(663996, 69515, 14476, '<td valign="top">This image tells a story and is nicely photographed.  Good one!</td>', 'This image tells a story and is nicely photographed.  Good one!', '2004-04-12 16:25:18.000000', NULL, 1),
(663997, 69383, 4008, '<td valign="top">The window is so bright, sharp and colorful that it competes for attention with the landscape. Feels almost like two images (I assume it is not).</td>', 'The window is so bright, sharp and colorful that it competes for attention with the landscape. Feels almost like two images (I assume it is not).', '2004-04-12 16:25:52.000000', NULL, 1),
(664004, 69439, 4008, '<td valign="top">Should have gone to the 5th floor (if there was one) to get rid of these electricity poles. And switch off the light inside to avoid reflections. Nice try but a bit too messy for me.</td>', 'Should have gone to the 5th floor (if there was one) to get rid of these electricity poles. And switch off the light inside to avoid reflections. Nice try but a bit too messy for me.', '2004-04-12 16:28:25.000000', NULL, 1),
(664005, 69562, 14476, '<td valign="top">This is imaginative and excellent framing.  If it was mine, I''d probably get rid of the printing and the marks on the glass.  Still, it''s a good image with good composition.  Good luck!</td>', 'This is imaginative and excellent framing.  If it was mine, I''d probably get rid of the printing and the marks on the glass.  Still, it''s a good image with good composition.  Good luck!', '2004-04-12 16:28:41.000000', NULL, 1),
(664007, 69132, 4543, '<td valign="top">Nicely done.  I see some reflections (2nd and 3rd row) but nothing really noticeable.  Well done! 9</td>', 'Nicely done.  I see some reflections (2nd and 3rd row) but nothing really noticeable.  Well done! 9', '2004-04-12 16:29:21.000000', NULL, 1),
(664010, 69132, 14476, '<td valign="top">Very, very nicely done!  Your composition works well and you found a unique window.  Good luck.</td>', 'Very, very nicely done!  Your composition works well and you found a unique window.  Good luck.', '2004-04-12 16:29:44.000000', NULL, 1),
(664012, 69554, 14476, '<td valign="top">This just glows on my screen.  I like the treatment you gave it very much.</td>', 'This just glows on my screen.  I like the treatment you gave it very much.', '2004-04-12 16:30:30.000000', NULL, 1),
(664019, 69637, 14476, '<td valign="top">Very nicely framed.  I"m glad you made sure the window was clean before you took the image.   It complements the composition.</td>', 'Very nicely framed.  I"m glad you made sure the window was clean before you took the image.   It complements the composition.', '2004-04-12 16:32:06.000000', NULL, 1),
(664020, 69138, 15495, '<td valign="top">Should have focused on the Flag.</td>', 'Should have focused on the Flag.', '2004-04-12 16:32:22.000000', NULL, 1),
(664027, 69671, 14476, '<td valign="top">I''d sure like to know how you got this picture so sharp at the speed you were going and with the tachometer near the redline!   (Hmmm, looks like California hills too.  ) This should do well in the Challenge.  9</td>', 'I''d sure like to know how you got this picture so sharp at the speed you were going and with the tachometer near the redline!   (Hmmm, looks like California hills too.  ) This should do well in the Challenge.  9', '2004-04-12 16:35:43.000000', NULL, 1),
(664029, 69639, 14476, '<td valign="top">This is a perfectly lovely artistic interpretation of the Challenge.  I wish you well lwith this beauty!   10</td>', 'This is a perfectly lovely artistic interpretation of the Challenge.  I wish you well lwith this beauty!   10', '2004-04-12 16:36:26.000000', NULL, 1),
(664032, 69037, 15495, '<td valign="top">Very Cool.</td>', 'Very Cool.', '2004-04-12 16:37:06.000000', NULL, 1),
(664034, 69383, 14476, '<td valign="top">Love your framing, love the view!  Well done.  8</td>', 'Love your framing, love the view!  Well done.  8', '2004-04-12 16:37:26.000000', NULL, 1),
(664038, 69161, 14476, '<td valign="top">You were in the right place at the right time for this excellent action shot.   Very sharp considering the circumstances!   10</td>', 'You were in the right place at the right time for this excellent action shot.   Very sharp considering the circumstances!   10', '2004-04-12 16:38:29.000000', NULL, 1),
(664042, 68688, 14476, '<td valign="top">A nicely artistic take on the challenge.  Good work!</td>', 'A nicely artistic take on the challenge.  Good work!', '2004-04-12 16:39:00.000000', NULL, 1),
(664043, 69308, 10867, '<td valign="top">I love the idea of this image and the colours you''ve captured, but I''m not sure that the photo is quite a "from the window" shot.</td>', 'I love the idea of this image and the colours you''ve captured, but I''m not sure that the photo is quite a "from the window" shot.', '2004-04-12 16:39:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(664047, 69531, 14476, '<td valign="top">Nice composition and colors in this one.</td>', 'Nice composition and colors in this one.', '2004-04-12 16:40:08.000000', NULL, 1),
(664048, 69159, 10867, '<td valign="top">Very nice!  I love the bright colour accents and the way the scenes are distributed in the various window panes.</td>', 'Very nice!  I love the bright colour accents and the way the scenes are distributed in the various window panes.', '2004-04-12 16:40:27.000000', NULL, 1),
(664050, 69383, 10867, '<td valign="top">An excellent choice of image for this challenge!  Very well executed, too!</td>', 'An excellent choice of image for this challenge!  Very well executed, too!', '2004-04-12 16:41:11.000000', NULL, 1),
(664052, 69134, 14476, '<td valign="top">This is very well seen and nicely photographed.  I do wish the window portion was in sharp focus.  That would give this image the Wow it needs for really high marks!  Still, it''s good as is.</td>', 'This is very well seen and nicely photographed.  I do wish the window portion was in sharp focus.  That would give this image the Wow it needs for really high marks!  Still, it''s good as is.', '2004-04-12 16:41:51.000000', NULL, 1),
(664054, 69631, 10867, '<td valign="top">Unfortunately, I''m afraid that your title is a bit too close to being apt for comfort.</td>', 'Unfortunately, I''m afraid that your title is a bit too close to being apt for comfort.', '2004-04-12 16:42:00.000000', NULL, 1),
(664058, 69312, 14476, '<td valign="top">What an interesting pattern in the shore you found in this image.  While I wish the window frame was in better focus, overall, it''s a nice photograph.</td>', 'What an interesting pattern in the shore you found in this image.  While I wish the window frame was in better focus, overall, it''s a nice photograph.', '2004-04-12 16:43:15.000000', NULL, 1),
(664063, 69256, 14476, '<td valign="top">I like the arty feel this photograph conveys.  Colors are nice as is the composition.  Could stand a little sharper focus but still, nice.</td>', 'I like the arty feel this photograph conveys.  Colors are nice as is the composition.  Could stand a little sharper focus but still, nice.', '2004-04-12 16:44:38.000000', NULL, 1),
(664071, 69395, 14476, '<td valign="top">This image is nicely composed and tells a story.  Maybe a little dark(bracketing sometimes helps) but still, a pleasant interpretation of the Challenge.</td>', 'This image is nicely composed and tells a story.  Maybe a little dark(bracketing sometimes helps) but still, a pleasant interpretation of the Challenge.', '2004-04-12 16:47:42.000000', NULL, 1),
(664084, 69028, 14476, '<td valign="top">I like the repetition of triangles in the window, the frame and in the mountain top.  If it was mine, I''d probably try it without the half-of-a-flag.  It is still a very, very nice interpretation of the Challenge.</td>', 'I like the repetition of triangles in the window, the frame and in the mountain top.  If it was mine, I''d probably try it without the half-of-a-flag.  It is still a very, very nice interpretation of the Challenge.', '2004-04-12 16:50:54.000000', NULL, 1),
(664107, 69040, 14476, '<td valign="top">This is a lovely interpretation of the challenge.  Beautifully photographed with good crispness and color.  If it was mine, I''d probably move that pot next to the green bottle out of the frame, but either way, it''s very, very nice.  I especially like the camera angle.  9</td>', 'This is a lovely interpretation of the challenge.  Beautifully photographed with good crispness and color.  If it was mine, I''d probably move that pot next to the green bottle out of the frame, but either way, it''s very, very nice.  I especially like the camera angle.  9', '2004-04-12 16:57:49.000000', NULL, 1),
(664141, 69042, 14476, '<td valign="top">Charming picture of a sweet looking cat.  Wish it was a bit clearer or less "noisy"... Glad you had your camera ready to capture the image.</td>', 'Charming picture of a sweet looking cat.  Wish it was a bit clearer or less "noisy"... Glad you had your camera ready to capture the image.', '2004-04-12 17:06:11.000000', NULL, 1),
(664165, 68397, 16775, '<td valign="top">perhaps this wants to be a little less "documentary/journalistic"...  other wise, not too shabby.  i also like the simple title reinforced by the stack of "work"... and what better way to deal with work than to look out the window</td>', 'perhaps this wants to be a little less "documentary/journalistic"...  other wise, not too shabby.  i also like the simple title reinforced by the stack of "work"... and what better way to deal with work than to look out the window', '2004-04-12 17:19:40.000000', NULL, 1),
(664180, 69134, 2333, '<td valign="top">I like your composition and choice of light, and what a beautiful subject! I think ther could be some added impact by bringing in the black point a bit, and applying a slight contrast boost. A bit more (genlt!) USM after resizing could help bring back out some of the great detail in the brickwork.</td>', 'I like your composition and choice of light, and what a beautiful subject! I think ther could be some added impact by bringing in the black point a bit, and applying a slight contrast boost. A bit more (genlt!) USM after resizing could help bring back out some of the great detail in the brickwork.', '2004-04-12 17:29:43.000000', NULL, 1),
(664193, 69042, 2333, '<td valign="top">A very evocative image, and one of my favorites of thi challenge. I really like the tones and the softness, as well as the cat''s expression. Good work!</td>', 'A very evocative image, and one of my favorites of thi challenge. I really like the tones and the softness, as well as the cat''s expression. Good work!', '2004-04-12 17:34:52.000000', NULL, 1),
(664198, 69512, 6405, '<td valign="top">Photo is little dark,need some level adjustment , but overal nice,6.</td>', 'Photo is little dark,need some level adjustment , but overal nice,6.', '2004-04-12 17:36:26.000000', NULL, 1),
(664201, 68414, 2333, '<td valign="top">What an incredibly moody piece!  very nice work. Only wish the position of the crossing framwork was higher in the image.</td>', 'What an incredibly moody piece!  very nice work. Only wish the position of the crossing framwork was higher in the image.', '2004-04-12 17:37:00.000000', NULL, 1),
(664205, 69577, 6405, '<td valign="top">Good sky details,7.</td>', 'Good sky details,7.', '2004-04-12 17:37:34.000000', NULL, 1),
(664210, 69656, 6405, '<td valign="top">Shadow of the child is taking away from the image,7.</td>', 'Shadow of the child is taking away from the image,7.', '2004-04-12 17:38:36.000000', NULL, 1),
(664211, 69510, 2333, '<td valign="top">A very original choice of viewpoint. I like the bit of undistorted windmill as a reference. the yellow of the vehicle plays well witht he blue tones.</td>', 'A very original choice of viewpoint. I like the bit of undistorted windmill as a reference. the yellow of the vehicle plays well witht he blue tones.', '2004-04-12 17:38:39.000000', NULL, 1),
(664214, 69642, 14863, '<td valign="top">Cool idea- Iove the sky</td>', 'Cool idea- Iove the sky', '2004-04-12 17:39:46.000000', NULL, 1),
(664217, 69653, 14863, '<td valign="top">Very cool- I love  how there''s the selective coloration. I wish I could see more of the bird but this  is  awesome 9</td>', 'Very cool- I love  how there''s the selective coloration. I wish I could see more of the bird but this  is  awesome 9', '2004-04-12 17:40:12.000000', NULL, 1),
(664220, 69160, 14863, '<td valign="top">So pretty-  the sunshine and flowers, just gorgeous  9</td>', 'So pretty-  the sunshine and flowers, just gorgeous  9', '2004-04-12 17:40:54.000000', NULL, 1),
(664223, 69534, 6405, '<td valign="top">It look like toy,very sharp capure and well composed,need little contrast / darkening to be done! 9</td>', 'It look like toy,very sharp capure and well composed,need little contrast / darkening to be done! 9', '2004-04-12 17:41:49.000000', NULL, 1),
(664224, 69629, 14863, '<td valign="top">Ahhhh! Creepy, man but this is really great. I sure hope this wins- 10 10 10 :D</td>', 'Ahhhh! Creepy, man but this is really great. I sure hope this wins- 10 10 10 :D', '2004-04-12 17:41:55.000000', NULL, 1),
(664225, 69535, 16318, '<td valign="top">do you wish you had known the sillouette (sp) challenge was coming up??</td>', 'do you wish you had known the sillouette (sp) challenge was coming up??', '2004-04-12 17:42:08.000000', NULL, 1),
(664226, 69054, 2333, '<td valign="top">Beautiful choice of composition. I very much like your color treatment. I might have been tempted to tne down (but not clone out) some of the specks on the window.</td>', 'Beautiful choice of composition. I very much like your color treatment. I might have been tempted to tne down (but not clone out) some of the specks on the window.', '2004-04-12 17:42:10.000000', NULL, 1),
(664234, 69318, 16318, '<td valign="top">good quality photo but not very interesting</td>', 'good quality photo but not very interesting', '2004-04-12 17:45:52.000000', NULL, 1),
(664245, 69539, 6405, '<td valign="top">Nice view from your room :-)  7</td>', 'Nice view from your room :-)  7', '2004-04-12 17:55:50.000000', NULL, 1),
(664247, 69319, 2333, '<td valign="top">Perfect exposure. I really like the white cat contrasted withthe rich wood tones. The spots on the glass add, not detract IMO.<br/>The slight tilt to the frame is distracting, as is the absence of frame on the top. Both situations can be fixed in PS.</td>', 'Perfect exposure. I really like the white cat contrasted withthe rich wood tones. The spots on the glass add, not detract IMO.The slight tilt to the frame is distracting, as is the absence of frame on the top. Both situations can be fixed in PS.', '2004-04-12 17:57:43.000000', NULL, 1),
(664249, 68396, 2333, '<td valign="top">Simple, elegant. The title definitely adds to the impact. Good work.</td>', 'Simple, elegant. The title definitely adds to the impact. Good work.', '2004-04-12 17:58:39.000000', NULL, 1),
(664254, 69439, 2333, '<td valign="top">Nice capture. I like the presence of the electrical lines, juxtaposed with the natural electrical power of the lightning. A touch of perspective correction in PS to straighten the RH frame would be a plus, IMO.</td>', 'Nice capture. I like the presence of the electrical lines, juxtaposed with the natural electrical power of the lightning. A touch of perspective correction in PS to straighten the RH frame would be a plus, IMO.', '2004-04-12 18:04:51.000000', NULL, 1),
(664257, 69544, 18512, '<td valign="top">I really like the tones and composition of this picture.</td>', 'I really like the tones and composition of this picture.', '2004-04-12 18:07:48.000000', NULL, 1),
(664259, 68873, 18512, '<td valign="top">Good idea! Well performed.</td>', 'Good idea! Well performed.', '2004-04-12 18:08:12.000000', NULL, 1),
(664261, 69256, 19159, '<td valign="top">I LOVE the color in this photo.  Beautiful.</td>', 'I LOVE the color in this photo.  Beautiful.', '2004-04-12 18:09:50.000000', NULL, 1),
(664266, 68873, 19159, '<td valign="top">Very creative shot...the girl in the photo is hot!  Ow ow!! ;)</td>', 'Very creative shot...the girl in the photo is hot!  Ow ow!! ;)', '2004-04-12 18:11:13.000000', NULL, 1),
(664268, 69548, 19159, '<td valign="top">Very catchy photo.  I don''t know why I like it especially, but I just do.  I think it makes me think of traveling or getting away.</td>', 'Very catchy photo.  I don''t know why I like it especially, but I just do.  I think it makes me think of traveling or getting away.', '2004-04-12 18:12:37.000000', NULL, 1),
(664277, 69639, 19159, '<td valign="top">Very nice.  Nice centering and alignment, and great colors.</td>', 'Very nice.  Nice centering and alignment, and great colors.', '2004-04-12 18:14:25.000000', NULL, 1),
(664280, 69608, 19159, '<td valign="top">I love it!  The focus is especially good.</td>', 'I love it!  The focus is especially good.', '2004-04-12 18:15:00.000000', NULL, 1),
(664282, 69582, 16780, '<td valign="top">Lovely view.  I''d probably like this image a bit better with less of the inside features &amp; more emphasis on the view.  Even just taking some of the plain top area away pulls my eyes more into the window.  Considering the difference in lighting between inside &amp; out...nice job of exposinig both well.  Also, I would have rotated this ever so slightly to the left to level out the water line.  <br/></td>', 'Lovely view.  I''d probably like this image a bit better with less of the inside features & more emphasis on the view.  Even just taking some of the plain top area away pulls my eyes more into the window.  Considering the difference in lighting between inside & out...nice job of exposinig both well.  Also, I would have rotated this ever so slightly to the left to level out the water line.  ', '2004-04-12 18:15:49.000000', NULL, 1),
(664298, 69386, 17937, '<td valign="top">Caught in the act...   I think I would like this even more if the aligned verticle...  Not sure though.  Would have to see.</td>', 'Caught in the act...   I think I would like this even more if the aligned verticle...  Not sure though.  Would have to see.', '2004-04-12 18:20:44.000000', NULL, 1),
(664300, 69637, 16780, '<td valign="top">Nicely done, but a bit too centered for my liking.  I have a feeling of wanting to see more  character &amp; detail leading to the window...perhaps from a bit off to one side.  The bright spot in the sky to the right is a little distracting.</td>', 'Nicely done, but a bit too centered for my liking.  I have a feeling of wanting to see more  character & detail leading to the window...perhaps from a bit off to one side.  The bright spot in the sky to the right is a little distracting.', '2004-04-12 18:20:52.000000', NULL, 1),
(664308, 68871, 17937, '<td valign="top">Very cool image.  Black and White was definitely the way to go here. (9)</td>', 'Very cool image.  Black and White was definitely the way to go here. (9)', '2004-04-12 18:25:17.000000', NULL, 1),
(664310, 69467, 17937, '<td valign="top">Intresting Window...</td>', 'Intresting Window...', '2004-04-12 18:26:32.000000', NULL, 1),
(664322, 69233, 18737, '<td valign="top">Great shot, love the way the top fits and the restaurant shows through the middel pane</td>', 'Great shot, love the way the top fits and the restaurant shows through the middel pane', '2004-04-12 18:30:39.000000', NULL, 1),
(664324, 69318, 18191, '<td valign="top">The subject behind the window is boring...it may have been more efective on much shallower DOF.</td>', 'The subject behind the window is boring...it may have been more efective on much shallower DOF.', '2004-04-12 18:31:15.000000', NULL, 1),
(664330, 69630, 16780, '<td valign="top">The bar across the bottom is distracting and there seems to be a green hue to everything below the bar &amp; sudden texture changes that I can''t quite figure out.  I thought it might be part of a cement window sill but it doesn''t carry over all the way, just ends.  The whole image seems to be tilted to the left.  Were you level or is it an illusion of an angled shore line across the water?  All the pole tops follow it, so I think a rotation to the right would fix it.<br/>Beautiful scene.</td>', 'The bar across the bottom is distracting and there seems to be a green hue to everything below the bar & sudden texture changes that I can''t quite figure out.  I thought it might be part of a cement window sill but it doesn''t carry over all the way, just ends.  The whole image seems to be tilted to the left.  Were you level or is it an illusion of an angled shore line across the water?  All the pole tops follow it, so I think a rotation to the right would fix it.Beautiful scene.', '2004-04-12 18:33:29.000000', NULL, 1),
(664333, 69054, 14620, '<td valign="top">I really like the treatment you used on this photo.  Makes the typical pet shot more interesting.  I also really like the composition.  Very cool.  If you check my profile you''ll see something similar, we think alike!  :-)  <br/> <br/>Best of luck to you!</td>', 'I really like the treatment you used on this photo.  Makes the typical pet shot more interesting.  I also really like the composition.  Very cool.  If you check my profile you''ll see something similar, we think alike!  :-)   Best of luck to you!', '2004-04-12 18:33:49.000000', NULL, 1),
(664365, 69472, 16780, '<td valign="top">I like the play of all the lines, but my eye''s are more drawn to the brighter yellow piece in top.  I probably would have cropped that out.  The bigger blue sky parts look artificially darkened...more gray than blue &amp; not matching the smaller areas along the bottom.  Too much use of burning tool?  Don''t know what program you use, but adjusting in the selective color adjustments in Photoshop might do a more natural job &amp; effect all the blue areas uniformly.<br/>This would have been a great parallel lines entry!</td>', 'I like the play of all the lines, but my eye''s are more drawn to the brighter yellow piece in top.  I probably would have cropped that out.  The bigger blue sky parts look artificially darkened...more gray than blue & not matching the smaller areas along the bottom.  Too much use of burning tool?  Don''t know what program you use, but adjusting in the selective color adjustments in Photoshop might do a more natural job & effect all the blue areas uniformly.This would have been a great parallel lines entry!', '2004-04-12 18:43:12.000000', NULL, 1),
(664395, 69312, 16780, '<td valign="top">Very nice....good clarity, level water line &amp; great color.  ALMOST put something similar in myself, but not confined to 1 window.  I prefer to see a bit more detail of the inside &amp; have a larger view of outside.  I had too many refections due to no polorizer for a new lens.   After the challenge, I''d love to know what lighthouse it is &amp; see other shots you took :) Good luck!</td>', 'Very nice....good clarity, level water line & great color.  ALMOST put something similar in myself, but not confined to 1 window.  I prefer to see a bit more detail of the inside & have a larger view of outside.  I had too many refections due to no polorizer for a new lens.   After the challenge, I''d love to know what lighthouse it is & see other shots you took :) Good luck!', '2004-04-12 19:02:30.000000', NULL, 1),
(664398, 69588, 16780, '<td valign="top">There''s just not enough contrast to jump out at you.  Maybe the color version would have had more character?  Spring is so full of color that it just seems odd in B&amp;W</td>', 'There''s just not enough contrast to jump out at you.  Maybe the color version would have had more character?  Spring is so full of color that it just seems odd in B&W', '2004-04-12 19:04:41.000000', NULL, 1),
(664400, 69439, 16780, '<td valign="top">Nice lightening catch!  I''ve had no luck with those.  The reflection in the window takes away from it.  A polorized filter could cut that.</td>', 'Nice lightening catch!  I''ve had no luck with those.  The reflection in the window takes away from it.  A polorized filter could cut that.', '2004-04-12 19:06:18.000000', NULL, 1),
(664407, 69671, 16780, '<td valign="top">Let''s see....driving a motor cycle at 120 mph &amp; taking pics.....<br/>Considering the circumstances, you did a GREAT job!  No over expoxed reflections, great clarity &amp;  very nice perspective.<br/>One question though....light out at 1:15am?  lol</td>', 'Let''s see....driving a motor cycle at 120 mph & taking pics.....Considering the circumstances, you did a GREAT job!  No over expoxed reflections, great clarity &  very nice perspective.One question though....light out at 1:15am?  lol', '2004-04-12 19:11:49.000000', NULL, 1),
(664414, 69216, 16780, '<td valign="top">Very nice &amp; different.  I probably would have cropped it down to get rid of a lot of the brighter window in the back.  It''s pulling my eyes away from the subject.  Looking at it with just a bit left above his head, I''m pulled right into his eyes.</td>', 'Very nice & different.  I probably would have cropped it down to get rid of a lot of the brighter window in the back.  It''s pulling my eyes away from the subject.  Looking at it with just a bit left above his head, I''m pulled right into his eyes.', '2004-04-12 19:15:11.000000', NULL, 1),
(664430, 69505, 16780, '<td valign="top">Great shot, but I probably would have focused on the pasture instead of the car features.</td>', 'Great shot, but I probably would have focused on the pasture instead of the car features.', '2004-04-12 19:27:24.000000', NULL, 1),
(664471, 69028, 11793, '<td valign="top">the flag pole, is kind of a distraction.<br/>the lines are interesting, and the view   nice.<br/></td>', 'the flag pole, is kind of a distraction.the lines are interesting, and the view   nice.', '2004-04-12 19:55:48.000000', NULL, 1),
(664472, 69540, 13035, '<td valign="top">I''ve piched you for a ribbon with this.  I love your composition and toning.  Good luck</td>', 'I''ve piched you for a ribbon with this.  I love your composition and toning.  Good luck', '2004-04-12 19:56:26.000000', NULL, 1),
