(664880, 69506, 259, '<td valign="top">nice view.  i would recommend cropping out the tiny bit outside the frame at the top of your picture.  overall a nice job.</td>', 'nice view.  i would recommend cropping out the tiny bit outside the frame at the top of your picture.  overall a nice job.', '2004-04-12 22:46:17.000000', NULL, 1),
