(665424, 69042, 8139, '<td valign="top">Nice and soft composition. I just had aligned the windows lines with the frame.<br/>There seems to be some grainy compression artifacts too. And some spots  could be cloned out.</td>', 'Nice and soft composition. I just had aligned the windows lines with the frame.There seems to be some grainy compression artifacts too. And some spots  could be cloned out.', '2004-04-13 07:10:23.000000', NULL, 1),
(665425, 69624, 8139, '<td valign="top">Nice compo and lighting. I like the overall mood of this.</td>', 'Nice compo and lighting. I like the overall mood of this.', '2004-04-13 07:12:45.000000', NULL, 1),
(665426, 69407, 8139, '<td valign="top">Vibrant colors, nice composition. The window frames are annoying, but that was part of the challenge.</td>', 'Vibrant colors, nice composition. The window frames are annoying, but that was part of the challenge.', '2004-04-13 07:15:16.000000', NULL, 1),
(665427, 69506, 8139, '<td valign="top">Soft, moody, emotional. I like this very much. 10</td>', 'Soft, moody, emotional. I like this very much. 10', '2004-04-13 07:20:03.000000', NULL, 1),
(665428, 69115, 8139, '<td valign="top">Add a subjet to this structure</td>', 'Add a subjet to this structure', '2004-04-13 07:25:02.000000', NULL, 1),
(665429, 68688, 8139, '<td valign="top">Nice compo. Aestetic. Well framed</td>', 'Nice compo. Aestetic. Well framed', '2004-04-13 07:27:32.000000', NULL, 1),
