(665469, 69506, 164, '<td valign="top">cool colors</td>', 'cool colors', '2004-04-13 09:03:47.000000', NULL, 1),
(665478, 69312, 16126, '<td valign="top">Interesting seascape, nice colors and composition. However, I don''t think the border really adds to the image, since it''s too dark and out of focus. Tighter cropping maybe?</td>', 'Interesting seascape, nice colors and composition. However, I don''t think the border really adds to the image, since it''s too dark and out of focus. Tighter cropping maybe?', '2004-04-13 09:19:30.000000', NULL, 1),
