(665484, 69577, 16126, '<td valign="top">Great view, a pity that the window doesn''t really add to the composition (window handles are even distracting). Tighter cropping to make it a (rectangular) triptych view might have been more interesting.</td>', 'Great view, a pity that the window doesn''t really add to the composition (window handles are even distracting). Tighter cropping to make it a (rectangular) triptych view might have been more interesting.', '2004-04-13 09:28:32.000000', NULL, 1),
(665486, 69323, 16126, '<td valign="top">Love this one! The combination of the different blues is awesome, perfect composition with one open and one closed window.</td>', 'Love this one! The combination of the different blues is awesome, perfect composition with one open and one closed window.', '2004-04-13 09:30:36.000000', NULL, 1),
(665490, 69506, 16126, '<td valign="top">Capture of the sunrise is great, but the window distracts somewhat. For example, the highest stone with the interestingly shaped edge in the foreground is obscured from view. Not sure how to solve that though, without creating other composition problems.</td>', 'Capture of the sunrise is great, but the window distracts somewhat. For example, the highest stone with the interestingly shaped edge in the foreground is obscured from view. Not sure how to solve that though, without creating other composition problems.', '2004-04-13 09:34:42.000000', NULL, 1),
(665493, 69028, 16126, '<td valign="top">The similarity in shapes of the mountain and the window makes this very nice. I think I would have cropped out the right edge of the window.</td>', 'The similarity in shapes of the mountain and the window makes this very nice. I think I would have cropped out the right edge of the window.', '2004-04-13 09:36:31.000000', NULL, 1),
