(665740, 68414, 18913, '<td valign="top">Love to know your settings on this one...very striking.  Unbelievable light and mood.  Fantastic, the best of the bunch.</td>', 'Love to know your settings on this one...very striking.  Unbelievable light and mood.  Fantastic, the best of the bunch.', '2004-04-13 13:30:09.000000', NULL, 1),
