(665748, 69644, 16095, '<td valign="top">This shot has great colors and overall good comp., but the rearview mirror being blocked out is distracting-I bet you could have selected the area and blurred it instead of completely blocking it out-I think the viewer''s eye would not focus on it as much!</td>', 'This shot has great colors and overall good comp., but the rearview mirror being blocked out is distracting-I bet you could have selected the area and blurred it instead of completely blocking it out-I think the viewer''s eye would not focus on it as much!', '2004-04-13 13:33:36.000000', NULL, 1),
(665754, 69554, 18913, '<td valign="top">Excellent subject matter but it''s hard for the viewer to decide what to focus on exactly.  I don''t mind photographs that are challenging and that have a lot going on because sometimes they produce excellent results but for this one, I think I would have either cropped it or done some kind of montage or focus on a particular pane or area.  Having said all that, it is a nice find.</td>', 'Excellent subject matter but it''s hard for the viewer to decide what to focus on exactly.  I don''t mind photographs that are challenging and that have a lot going on because sometimes they produce excellent results but for this one, I think I would have either cropped it or done some kind of montage or focus on a particular pane or area.  Having said all that, it is a nice find.', '2004-04-13 13:37:24.000000', NULL, 1),
(665756, 69312, 1024, '<td valign="top">Wonderfully executed.</td>', 'Wonderfully executed.', '2004-04-13 13:37:27.000000', NULL, 1),
