(671136, 69257, 12131, '<td valign="top">Interesting distortion. 7</td>', 'Interesting distortion. 7', '2004-04-15 23:29:29.000000', NULL, 1),
(671137, 69544, 12131, '<td valign="top">I like the clarity and the way the window is reflected in the glass.  I just wonder at the title.  Also, I wonder what could carve those trenches so well.  I''m guessing its a dried up creek bed.  I like it.</td>', 'I like the clarity and the way the window is reflected in the glass.  I just wonder at the title.  Also, I wonder what could carve those trenches so well.  I''m guessing its a dried up creek bed.  I like it.', '2004-04-15 23:31:01.000000', NULL, 1),
(671138, 69472, 12131, '<td valign="top">Love the focus and the multiple possibilities for "window view".  Very clear, and colorful. 9</td>', 'Love the focus and the multiple possibilities for "window view".  Very clear, and colorful. 9', '2004-04-15 23:31:57.000000', NULL, 1),
(671139, 69360, 12131, '<td valign="top">I feel like I''m looking at a reflection rather than through a window, for how clear it is.  I like it.</td>', 'I feel like I''m looking at a reflection rather than through a window, for how clear it is.  I like it.', '2004-04-15 23:33:50.000000', NULL, 1),
(671140, 69386, 12131, '<td valign="top">Great capture.  I''m putting this in my favorites when it comes out.</td>', 'Great capture.  I''m putting this in my favorites when it comes out.', '2004-04-15 23:34:25.000000', NULL, 1),
(671144, 69550, 12131, '<td valign="top">I don''t like what''s on top, the curtain or drape or whathaveyou, but I like the spiky flower at the bottom and the rainy feel to the whole thing.</td>', 'I don''t like what''s on top, the curtain or drape or whathaveyou, but I like the spiky flower at the bottom and the rainy feel to the whole thing.', '2004-04-15 23:36:43.000000', NULL, 1),
