(671151, 69648, 16075, '<td valign="top">Nicely compose and good color but a little blurry.</td>', 'Nicely compose and good color but a little blurry.', '2004-04-15 23:40:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(671157, 69037, 12131, '<td valign="top">It''s a beautiful image but I can''t see the window in it, except that eerie blackness that shouldn''t follow the light.  I love the effect but how did you do it?  7</td>', 'It''s a beautiful image but I can''t see the window in it, except that eerie blackness that shouldn''t follow the light.  I love the effect but how did you do it?  7', '2004-04-15 23:43:00.000000', NULL, 1),
(671160, 69348, 16075, '<td valign="top">Good color...but this does not seem to convey the topic.</td>', 'Good color...but this does not seem to convey the topic.', '2004-04-15 23:44:04.000000', NULL, 1),
(671163, 69312, 12131, '<td valign="top">Very interesting beach.  I wonder what makes the waves come in like that.  Were those . . . rushes put there to keep it at bay? Kind of cool effect.</td>', 'Very interesting beach.  I wonder what makes the waves come in like that.  Were those . . . rushes put there to keep it at bay? Kind of cool effect.', '2004-04-15 23:46:48.000000', NULL, 1),
(671164, 69439, 16075, '<td valign="top">Too bad those poles and power (or phone?) lines mess up what would otherwise be a beautiful view!</td>', 'Too bad those poles and power (or phone?) lines mess up what would otherwise be a beautiful view!', '2004-04-15 23:47:03.000000', NULL, 1),
(671166, 69678, 12131, '<td valign="top">That figure is scary to me.  I love the window though and centering.  Beautiful view.<br/><br/><i>Message edited by author 2004-04-23 18:22:02.</i></td>', 'That figure is scary to me.  I love the window though and centering.  Beautiful view.', '2004-04-15 23:48:31.000000', '2004-04-23 19:22:02.000000', 1),
(671167, 69383, 16075, '<td valign="top">Too bad you didn''t have some of the wall instead of cropping to the window frame...for some reason this does not look real.  Beautiful view!  Lucky you if this is a view from your place!!!</td>', 'Too bad you didn''t have some of the wall instead of cropping to the window frame...for some reason this does not look real.  Beautiful view!  Lucky you if this is a view from your place!!!', '2004-04-15 23:50:23.000000', NULL, 1),
(671168, 69465, 16075, '<td valign="top">Nicely composed.<br/></td>', 'Nicely composed.', '2004-04-15 23:51:28.000000', NULL, 1),
(671170, 69556, 16075, '<td valign="top">Beautiful composition and lighting...very nicely done!</td>', 'Beautiful composition and lighting...very nicely done!', '2004-04-15 23:52:22.000000', NULL, 1),
(671172, 69094, 16075, '<td valign="top">WOW~</td>', 'WOW~', '2004-04-15 23:56:09.000000', NULL, 1),
(671174, 69618, 16075, '<td valign="top">Cuteness factor alone gives this a high score...but it is also a nice photo!</td>', 'Cuteness factor alone gives this a high score...but it is also a nice photo!', '2004-04-15 23:58:59.000000', NULL, 1),
(671176, 69588, 16075, '<td valign="top">Sorry...I really think you needed color to pull this one off...it does nothing for me.</td>', 'Sorry...I really think you needed color to pull this one off...it does nothing for me.', '2004-04-15 23:59:49.000000', NULL, 1),
(671179, 69671, 11926, '<td valign="top">Wow that is a challenge!  Taking a sharp picture, riding a bike at 120 and getting a well framed image.  congratulations!!</td>', 'Wow that is a challenge!  Taking a sharp picture, riding a bike at 120 and getting a well framed image.  congratulations!!', '2004-04-16 00:04:08.000000', NULL, 1),
(671184, 69671, 16075, '<td valign="top">Please don''t do that again.  It is dangerous enough to drive 120 mph without trying to take a picture while doing it!  I don''t know how you managed to get a picture like this without a blur when going so fast.  Bye the way...your clock must be wrong...and my brother always gives me a bad time about my clocks being off.  At least I don''t advertise it in a photograph for all to see.</td>', 'Please don''t do that again.  It is dangerous enough to drive 120 mph without trying to take a picture while doing it!  I don''t know how you managed to get a picture like this without a blur when going so fast.  Bye the way...your clock must be wrong...and my brother always gives me a bad time about my clocks being off.  At least I don''t advertise it in a photograph for all to see.', '2004-04-16 00:11:24.000000', NULL, 1),
(671215, 69323, 20247, '<td valign="top">clean and simple.. :) <br/>I just wish that the bg was in focus, but I know the limitations of my own digicam so there''s nothing really to say about that.</td>', 'clean and simple.. :) I just wish that the bg was in focus, but I know the limitations of my own digicam so there''s nothing really to say about that.', '2004-04-16 00:37:52.000000', NULL, 1),
(671274, 69407, 8891, '<td valign="top">Like the colors and I can it amuses my eye to see how that and the rain you caught almost make it look like a violent wind blown storm rather than a calm spring shower.  The light dictates otherwise. Nice job.</td>', 'Like the colors and I can it amuses my eye to see how that and the rain you caught almost make it look like a violent wind blown storm rather than a calm spring shower.  The light dictates otherwise. Nice job.', '2004-04-16 01:44:14.000000', NULL, 1),
(671278, 69629, 8891, '<td valign="top">What a lovely little scena, but why must someone always introduce a violent theme into the challenge? It''s a good picture, but could you lighten up? JeeZ. Guess you''re one of the flower kitty haters as well. <br/>Well it is good as it is....I will not vote it down because of the violent angel, the shot angle is freat and the exposure is well done.   Watch a "G" rated film and try not retch...there is a lot of good in the world.</td>', 'What a lovely little scena, but why must someone always introduce a violent theme into the challenge? It''s a good picture, but could you lighten up? JeeZ. Guess you''re one of the flower kitty haters as well. Well it is good as it is....I will not vote it down because of the violent angel, the shot angle is freat and the exposure is well done.   Watch a "G" rated film and try not retch...there is a lot of good in the world.', '2004-04-16 01:48:46.000000', NULL, 1),
(671282, 68505, 8891, '<td valign="top">difficult shot to take and I would understand for that reason the use of monotone. Like it. BUT I iwhse it was not centered so horiziontally.  I might have been more intereresting on an angle, but then there is that pesky exposure problem. Good job none the less.</td>', 'difficult shot to take and I would understand for that reason the use of monotone. Like it. BUT I iwhse it was not centered so horiziontally.  I might have been more intereresting on an angle, but then there is that pesky exposure problem. Good job none the less.', '2004-04-16 01:50:43.000000', NULL, 1),
(671283, 69390, 3724, '<td valign="top">A very interesting effect and mergeing of the close sill and the ground below....  the visual illusion that they are on one plane, created with the colour is remarkable.   Really a unique view.</td>', 'A very interesting effect and mergeing of the close sill and the ground below....  the visual illusion that they are on one plane, created with the colour is remarkable.   Really a unique view.', '2004-04-16 01:50:53.000000', NULL, 1),
(671302, 69519, 3724, '<td valign="top">Composition keeps me interested in this.....  a few points off for some grit, never the less amoung the better b&amp;w in this challenge.</td>', 'Composition keeps me interested in this.....  a few points off for some grit, never the less amoung the better b&w in this challenge.', '2004-04-16 02:05:28.000000', NULL, 1),
(671317, 69254, 3724, '<td valign="top">for me this is a good b&amp;w.....  subtle and seamless dof fades front to the very sharp focused fly..... fffffff  composition elements  of soft H came w/ formal design mix including beveled jewels and chipped glass is interesting.</td>', 'for me this is a good b&w.....  subtle and seamless dof fades front to the very sharp focused fly..... fffffff  composition elements  of soft H came w/ formal design mix including beveled jewels and chipped glass is interesting.', '2004-04-16 02:30:14.000000', NULL, 1),
(671324, 69629, 259, '<td valign="top">well done.  the composition is great.</td>', 'well done.  the composition is great.', '2004-04-16 02:46:14.000000', NULL, 1),
(671325, 69639, 3724, '<td valign="top">Good colour work on this very formal piece...... sharp focused yellow flower enhanced by the beveled jewel really pops out from the green translucent light of the window.   A good thoughtful design.   Enjoyable to view.</td>', 'Good colour work on this very formal piece...... sharp focused yellow flower enhanced by the beveled jewel really pops out from the green translucent light of the window.   A good thoughtful design.   Enjoyable to view.', '2004-04-16 02:46:24.000000', NULL, 1),
(671326, 69323, 259, '<td valign="top">all the different shades make your shot stand out above the rest.</td>', 'all the different shades make your shot stand out above the rest.', '2004-04-16 02:47:21.000000', NULL, 1),
(671328, 68414, 259, '<td valign="top">looks like some sorta futuristic city on another planet.  kind of reminds me of sim city as well.  interesting sky too.</td>', 'looks like some sorta futuristic city on another planet.  kind of reminds me of sim city as well.  interesting sky too.', '2004-04-16 02:53:08.000000', NULL, 1),
(671329, 69540, 259, '<td valign="top">really good toning.  it sets a strong mood.</td>', 'really good toning.  it sets a strong mood.', '2004-04-16 02:54:07.000000', NULL, 1),
(671337, 68688, 3724, '<td valign="top">An interesting combination of translucent rectangle glass textures.  The palm fond  and wrought iron placed and existing behind the glass creates added levels of visual texture.  Pretty.</td>', 'An interesting combination of translucent rectangle glass textures.  The palm fond  and wrought iron placed and existing behind the glass creates added levels of visual texture.  Pretty.', '2004-04-16 03:05:23.000000', NULL, 1),
(671362, 69525, 10170, '<td valign="top">Very nice effect you''ve created here.</td>', 'Very nice effect you''ve created here.', '2004-04-16 04:02:45.000000', NULL, 1),
(671371, 69624, 10170, '<td valign="top">I love the atmosphere created here, and the photo in general.  Great stuff.</td>', 'I love the atmosphere created here, and the photo in general.  Great stuff.', '2004-04-16 04:10:36.000000', NULL, 1),
(671374, 69677, 20254, '<td valign="top">This looks like you video taped your cat ten years ago made ten copies of the tape and then took a picture of it while it was playing on your TV</td>', 'This looks like you video taped your cat ten years ago made ten copies of the tape and then took a picture of it while it was playing on your TV', '2004-04-16 04:13:37.000000', NULL, 1),
(671376, 69653, 10170, '<td valign="top">Excellent use of desaturation. 10</td>', 'Excellent use of desaturation. 10', '2004-04-16 04:18:27.000000', NULL, 1),
(671377, 69681, 10170, '<td valign="top">Love the way the window frame works here.</td>', 'Love the way the window frame works here.', '2004-04-16 04:19:18.000000', NULL, 1),
(671379, 69618, 10170, '<td valign="top">Simply too cute for words, and meets the challenge perfectly.  Great shot!</td>', 'Simply too cute for words, and meets the challenge perfectly.  Great shot!', '2004-04-16 04:20:40.000000', NULL, 1),
(671380, 69650, 10170, '<td valign="top">I like the focus here.</td>', 'I like the focus here.', '2004-04-16 04:21:49.000000', NULL, 1),
(671382, 69505, 10170, '<td valign="top">Excellent.  I love the cracks in the window especially.</td>', 'Excellent.  I love the cracks in the window especially.', '2004-04-16 04:24:22.000000', NULL, 1),
(671392, 69386, 10170, '<td valign="top">Love the focus/DOF here.</td>', 'Love the focus/DOF here.', '2004-04-16 04:40:57.000000', NULL, 1),
(671401, 69540, 10170, '<td valign="top">Exceptional use of light.  Love it.</td>', 'Exceptional use of light.  Love it.', '2004-04-16 04:44:56.000000', NULL, 1),
(671430, 69678, 4008, '<td valign="top">One of the best in this challenge, good to have a mysterious subject in the middle, but also an interesting window with lots of detail in the frame and doors.</td>', 'One of the best in this challenge, good to have a mysterious subject in the middle, but also an interesting window with lots of detail in the frame and doors.', '2004-04-16 06:23:09.000000', NULL, 1),
(671432, 69540, 4008, '<td valign="top">One of the best. interesting view, great composition, love the color, and good to have that one anonymous person in there.</td>', 'One of the best. interesting view, great composition, love the color, and good to have that one anonymous person in there.', '2004-04-16 06:24:17.000000', NULL, 1),
(671433, 69111, 4008, '<td valign="top">I like it. It looks like 4 paintings on a wall. Could choice of viewpoint, good to leave the empty space around it.</td>', 'I like it. It looks like 4 paintings on a wall. Could choice of viewpoint, good to leave the empty space around it.', '2004-04-16 06:24:34.000000', NULL, 1),
(671444, 69319, 1368, '<td valign="top">Beautiful! I have 2 white cats So you hit me with this one :D Great shot :) Good luck</td>', 'Beautiful! I have 2 white cats So you hit me with this one :D Great shot :) Good luck', '2004-04-16 07:00:17.000000', NULL, 1),
(671453, 68414, 1368, '<td valign="top">Awesome shot! Looks unreal, great colors, I assume you were in a train :) Good job - 10</td>', 'Awesome shot! Looks unreal, great colors, I assume you were in a train :) Good job - 10', '2004-04-16 07:21:15.000000', NULL, 1),
(671480, 69644, 1368, '<td valign="top">Beautiful wiev But the color layers ruins alot As it looks fake, you should have taken more time and done it better, anyway good luck :)</td>', 'Beautiful wiev But the color layers ruins alot As it looks fake, you should have taken more time and done it better, anyway good luck :)', '2004-04-16 08:01:45.000000', NULL, 1),
(671481, 69259, 1368, '<td valign="top">Beautiful picture But its a bit out of focus, and it ruins it cause it doesnt feel as good to look at it as if it were in good sharp focus, or soft focus could have worked well here too, but not out of focus, anyway good luck in future challenges :)</td>', 'Beautiful picture But its a bit out of focus, and it ruins it cause it doesnt feel as good to look at it as if it were in good sharp focus, or soft focus could have worked well here too, but not out of focus, anyway good luck in future challenges :)', '2004-04-16 08:05:00.000000', NULL, 1),
(671486, 69042, 1368, '<td valign="top">This is such a beautiful picture, got this dreamy feeling to it, very moody, one of my favorites in this challenge, good luck - 10</td>', 'This is such a beautiful picture, got this dreamy feeling to it, very moody, one of my favorites in this challenge, good luck - 10', '2004-04-16 08:08:40.000000', NULL, 1),
(671538, 69518, 15407, '<td valign="top">Very nice lloking dog!  Somehow the effect of the window has been lost... almost as if a differnt picture of the dog was placed on this side of the window.</td>', 'Very nice lloking dog!  Somehow the effect of the window has been lost... almost as if a differnt picture of the dog was placed on this side of the window.', '2004-04-16 09:19:06.000000', NULL, 1),
(671548, 69671, 10818, '<td valign="top">Cool, nice photo.</td>', 'Cool, nice photo.', '2004-04-16 09:26:32.000000', NULL, 1),
(671585, 68785, 5891, '<td valign="top">i gave this one a ribbon (kis of death)<br/>it was a very good picture<br/>the use of color made it great<br/>nice idea and edit</td>', 'i gave this one a ribbon (kis of death)it was a very good picturethe use of color made it greatnice idea and edit', '2004-04-16 10:22:39.000000', NULL, 1),
(671636, 69671, 12253, '<td valign="top">This is quite wonderful and one of my top picks.  However: I wonder if the cycle itself was added in PS?  It''s an amazing capture if you were really going 120 mph at the time (and lucky you made it back to post it), and how could it be 1:15 AM and be so light out?</td>', 'This is quite wonderful and one of my top picks.  However: I wonder if the cycle itself was added in PS?  It''s an amazing capture if you were really going 120 mph at the time (and lucky you made it back to post it), and how could it be 1:15 AM and be so light out?', '2004-04-16 11:31:17.000000', NULL, 1),
(671650, 68871, 9821, '<td valign="top">great</td>', 'great', '2004-04-16 11:52:26.000000', NULL, 1),
(671651, 69094, 9821, '<td valign="top">i wish i was kicking back on that boat right now :)  9</td>', 'i wish i was kicking back on that boat right now :)  9', '2004-04-16 11:53:07.000000', NULL, 1),
(671667, 69255, 2764, '<td valign="top">By far the best image for windows,  This is really lovely 10</td>', 'By far the best image for windows,  This is really lovely 10', '2004-04-16 12:18:55.000000', NULL, 1),
(671675, 69631, 2764, '<td valign="top">I like your boring window - it is such a simple photo but tells a story none the less.  the lace has a homey irish feel.  it is night yet there are few lights outside.  there is no shade so it must be a safe place.  the curtain is slghtly titled, feels like a bit of a breeze.  Nice - 9<br/></td>', 'I like your boring window - it is such a simple photo but tells a story none the less.  the lace has a homey irish feel.  it is night yet there are few lights outside.  there is no shade so it must be a safe place.  the curtain is slghtly titled, feels like a bit of a breeze.  Nice - 9', '2004-04-16 12:23:20.000000', NULL, 1),
(671708, 69348, 671, '<td valign="top">It is a beautiful picture, but not enough of the window frame is showing.  I give this one an 8.</td>', 'It is a beautiful picture, but not enough of the window frame is showing.  I give this one an 8.', '2004-04-16 12:57:19.000000', NULL, 1),
(671712, 69467, 671, '<td valign="top">The sun''s rays echoing the shape of the window frame is very effective.  Also the placement of the rays in the angle of the frame, and the placement of the spire of the distant building all add up to an excellent framing job.    I give this one a 9.0</td>', 'The sun''s rays echoing the shape of the window frame is very effective.  Also the placement of the rays in the angle of the frame, and the placement of the spire of the distant building all add up to an excellent framing job.    I give this one a 9.0', '2004-04-16 12:59:15.000000', NULL, 1),
(671714, 69132, 6008, '<td valign="top">I really like this, I think it''s my fav of the challenge. I like the framing of the window, the unusual panes adds interest too. The view is great, and compositionally with foreground/background elements it really connects. The toning is great too. Not a thing I would change!</td>', 'I really like this, I think it''s my fav of the challenge. I like the framing of the window, the unusual panes adds interest too. The view is great, and compositionally with foreground/background elements it really connects. The toning is great too. Not a thing I would change!', '2004-04-16 13:00:52.000000', NULL, 1),
(671729, 69255, 6008, '<td valign="top">Good use of black and white to emphasize the tonal range and play of light and shadow. I like the natural light illuminating his face, it gives it a somewhat ''wonder'' feel to it. The only nitpick is what I think is his hand opening up the curtain. It''s not clearly defined as a hand so I partly wonder if it is something else, and also it seems to be ''growing'' out of the top of his head, which makes it somewhat of a distraction.</td>', 'Good use of black and white to emphasize the tonal range and play of light and shadow. I like the natural light illuminating his face, it gives it a somewhat ''wonder'' feel to it. The only nitpick is what I think is his hand opening up the curtain. It''s not clearly defined as a hand so I partly wonder if it is something else, and also it seems to be ''growing'' out of the top of his head, which makes it somewhat of a distraction.', '2004-04-16 13:08:19.000000', NULL, 1),
(671735, 69319, 6008, '<td valign="top">The title reminds me of the song ''how much is that doggie in the window''. The natural framing of the pane is good, although not perfectly straight, but I dont think that really matters. White subjects can be tough, and the exposure is not bad except for the hot spot near his/her right/our left ear. You still managed to get a lot of the details on the fur elsewhere, though, and that gives it a nice fluffy look. I''m assuming you desat the background also, and I think it works well to isolate the subject. I also like the rain/dirt spots on the window, it gives it more realism and atmosphere.</td>', 'The title reminds me of the song ''how much is that doggie in the window''. The natural framing of the pane is good, although not perfectly straight, but I dont think that really matters. White subjects can be tough, and the exposure is not bad except for the hot spot near his/her right/our left ear. You still managed to get a lot of the details on the fur elsewhere, though, and that gives it a nice fluffy look. I''m assuming you desat the background also, and I think it works well to isolate the subject. I also like the rain/dirt spots on the window, it gives it more realism and atmosphere.', '2004-04-16 13:12:41.000000', NULL, 1),
(671740, 69554, 6008, '<td valign="top">I like the background panes with what seems like different colored glass and the way the light hits them different. The overall feeling I get from this is somewhat chaotic with no singular focal point. From bricks to reflections to background glass to what is beyond those. There is also something about the bricks that do not seem quite right, I dont know if it''s the coloration or too much yellow hue shift or what. I dont dislike it, and it''s not a bad shot, I''m just left feeling... confused, I guess.</td>', 'I like the background panes with what seems like different colored glass and the way the light hits them different. The overall feeling I get from this is somewhat chaotic with no singular focal point. From bricks to reflections to background glass to what is beyond those. There is also something about the bricks that do not seem quite right, I dont know if it''s the coloration or too much yellow hue shift or what. I dont dislike it, and it''s not a bad shot, I''m just left feeling... confused, I guess.', '2004-04-16 13:17:18.000000', NULL, 1),
(671744, 69407, 6008, '<td valign="top">At first I thought it was snow, but after seeing the title I''m guessing it''s actually rain. Well there goes ''wow snow and flower petals in the same shot'' theory. The colors are vibrant, the rain/show makes it more different than the standard view of next door through a window look. The placement of the frame is good, but the lines are not very straight. Not a bad shot.</td>', 'At first I thought it was snow, but after seeing the title I''m guessing it''s actually rain. Well there goes ''wow snow and flower petals in the same shot'' theory. The colors are vibrant, the rain/show makes it more different than the standard view of next door through a window look. The placement of the frame is good, but the lines are not very straight. Not a bad shot.', '2004-04-16 13:20:14.000000', NULL, 1),
(671754, 69487, 6999, '<td valign="top">Another one! This really isn''t what the challenge asked for ... had you taken it from the other side of the window, maybe ... Having said that, there are elements to the shot that I like, especially the contrast of the dress(?) and the plainness of the curtains. The figure seems under-exposed however, as is not unusual against a white-ish background, and the lack of any visible face perhaps takes some character out of the shot.</td>', 'Another one! This really isn''t what the challenge asked for ... had you taken it from the other side of the window, maybe ... Having said that, there are elements to the shot that I like, especially the contrast of the dress(?) and the plainness of the curtains. The figure seems under-exposed however, as is not unusual against a white-ish background, and the lack of any visible face perhaps takes some character out of the shot.', '2004-04-16 13:27:49.000000', NULL, 1),
(671757, 69531, 6999, '<td valign="top">Like this. I do wish you''d perhaps used more processing to bring the balance of exposure of the frame and the sky closer together - you might at least have been eble to keep more definition in the silhouette of the tree.</td>', 'Like this. I do wish you''d perhaps used more processing to bring the balance of exposure of the frame and the sky closer together - you might at least have been eble to keep more definition in the silhouette of the tree.', '2004-04-16 13:29:32.000000', NULL, 1),
(671769, 69054, 6999, '<td valign="top">Despite my initial reaction to the toning here - green! - I rather like this shot, and it''s growing on me. I''m sure it will be far too weird for the majority on the site, however.</td>', 'Despite my initial reaction to the toning here - green! - I rather like this shot, and it''s growing on me. I''m sure it will be far too weird for the majority on the site, however.', '2004-04-16 13:36:06.000000', NULL, 1),
(671781, 69383, 6999, '<td valign="top">Seems kind of unlikely for interior light to be striking the window just like that :-) Is this a case of taking a window to a location and shooting through it? Full marks for endeavour, then.</td>', 'Seems kind of unlikely for interior light to be striking the window just like that :-) Is this a case of taking a window to a location and shooting through it? Full marks for endeavour, then.', '2004-04-16 13:54:03.000000', NULL, 1),
(671784, 69547, 6999, '<td valign="top">Reminds me of the building behind the Font Magica in Barcelona - only doesn''t seem to be high enough, so I''m not sure. Good capture of an interesting display however.</td>', 'Reminds me of the building behind the Font Magica in Barcelona - only doesn''t seem to be high enough, so I''m not sure. Good capture of an interesting display however.', '2004-04-16 13:56:42.000000', NULL, 1),
(671787, 69582, 6999, '<td valign="top">Now I would get the washing up done if I lived there, I''m sure :-) First reaction is that the square aspect ration of the shot is pecualiar - but in fact it serves to present the picture through the windows as something alien to this interior domestic scene - helped of course by the interio flash illumination. Makes that sunset (rise?) seem even more other-worldly. Good work keeping enough bounce of the glass, and not quite over-powering tthe existing interior light.</td>', 'Now I would get the washing up done if I lived there, I''m sure :-) First reaction is that the square aspect ration of the shot is pecualiar - but in fact it serves to present the picture through the windows as something alien to this interior domestic scene - helped of course by the interio flash illumination. Makes that sunset (rise?) seem even more other-worldly. Good work keeping enough bounce of the glass, and not quite over-powering tthe existing interior light.', '2004-04-16 14:01:46.000000', NULL, 1),
(671790, 69318, 6999, '<td valign="top">Love the suitability of this very neat and pleasant suburban scene with the absolutel compatrmentalising of the window frame. Good work.</td>', 'Love the suitability of this very neat and pleasant suburban scene with the absolutel compatrmentalising of the window frame. Good work.', '2004-04-16 14:04:39.000000', NULL, 1),
