(672730, 69407, 7743, '<td valign="top">The colours are amazing and the rain adds tremendous contrast and texture to the image.  Unfortunately the window frame seems to take away from the image.  Maybe a different angle would have worked better.  6</td>', 'The colours are amazing and the rain adds tremendous contrast and texture to the image.  Unfortunately the window frame seems to take away from the image.  Maybe a different angle would have worked better.  6', '2004-04-17 08:42:46.000000', NULL, 1),
(672738, 69360, 15810, '<td valign="top">Nice shot, Using photoshop''s Transform &gt; Perspective tool would have enabled you to straighten up the window''s vertical edges to make for a better overall frame.</td>', 'Nice shot, Using photoshop''s Transform > Perspective tool would have enabled you to straighten up the window''s vertical edges to make for a better overall frame.', '2004-04-17 09:12:13.000000', NULL, 1),
(672740, 69619, 15810, '<td valign="top">Sorry I cant see the "window glass or frame" here to tell the viewer it''s been taken from a window as per challenge????. There is some reflection there but it''s confusing rather than adding to the shot.</td>', 'Sorry I cant see the "window glass or frame" here to tell the viewer it''s been taken from a window as per challenge????. There is some reflection there but it''s confusing rather than adding to the shot.', '2004-04-17 09:15:00.000000', NULL, 1),
(672741, 69577, 15810, '<td valign="top">Lovely shot, beautiful view, good exposure.</td>', 'Lovely shot, beautiful view, good exposure.', '2004-04-17 09:15:42.000000', NULL, 1),
(672742, 68873, 15810, '<td valign="top">Brilliant, one of my faves. 10</td>', 'Brilliant, one of my faves. 10', '2004-04-17 09:16:13.000000', NULL, 1),
(672743, 69550, 15810, '<td valign="top">Nice, you could re-submit to silhouettes too!</td>', 'Nice, you could re-submit to silhouettes too!', '2004-04-17 09:16:43.000000', NULL, 1),
(672745, 69234, 15810, '<td valign="top">Great shot beautifully captured by your steep angle.</td>', 'Great shot beautifully captured by your steep angle.', '2004-04-17 09:18:00.000000', NULL, 1),
(672746, 69233, 15810, '<td valign="top">great shot, nice use of B&amp;W</td>', 'great shot, nice use of B&W', '2004-04-17 09:18:26.000000', NULL, 1),
(672747, 69510, 15810, '<td valign="top">I like this, (I suspect a lot of people wont) good work.</td>', 'I like this, (I suspect a lot of people wont) good work.', '2004-04-17 09:19:35.000000', NULL, 1),
(672749, 68967, 15810, '<td valign="top">Nice idea, do I score each window view then add the two together for the final  number?</td>', 'Nice idea, do I score each window view then add the two together for the final  number?', '2004-04-17 09:20:47.000000', NULL, 1),
(672750, 69160, 15810, '<td valign="top">Stunning colours, looks like something on a calender for springtime. Not sure if your window frame is pronounced enough to "be" the frame rather than a dark smudge. Lovely shot though</td>', 'Stunning colours, looks like something on a calender for springtime. Not sure if your window frame is pronounced enough to "be" the frame rather than a dark smudge. Lovely shot though', '2004-04-17 09:22:34.000000', NULL, 1),
(672758, 69671, 19474, '<td valign="top">great shot, very clear how is the camera mounted to stop vibrations and how did you release the shutter ?</td>', 'great shot, very clear how is the camera mounted to stop vibrations and how did you release the shutter ?', '2004-04-17 09:53:53.000000', NULL, 1),
(672761, 68717, 15810, '<td valign="top">Nice, I like this. The semi transparent window makes me peer to see through it. Nice composition.</td>', 'Nice, I like this. The semi transparent window makes me peer to see through it. Nice composition.', '2004-04-17 10:00:37.000000', NULL, 1),
(672763, 69518, 15810, '<td valign="top">great shot, love the expression on the dogs face and the alertness you''ve captured.</td>', 'great shot, love the expression on the dogs face and the alertness you''ve captured.', '2004-04-17 10:02:17.000000', NULL, 1),
(672764, 69257, 15810, '<td valign="top">Love the effect of the old glass.  Nice shot...dark and gloomy ....UK spring?</td>', 'Love the effect of the old glass.  Nice shot...dark and gloomy ....UK spring?', '2004-04-17 10:04:59.000000', NULL, 1),
(672765, 69383, 15810, '<td valign="top">Stunning.  Very very well done.</td>', 'Stunning.  Very very well done.', '2004-04-17 10:05:53.000000', NULL, 1),
(672767, 69556, 15810, '<td valign="top">great shot and fabulous use of natural light.</td>', 'great shot and fabulous use of natural light.', '2004-04-17 10:07:47.000000', NULL, 1),
(672768, 68785, 15810, '<td valign="top">personally I dont like the selective desaturation you''ve done here, I''d lke to see the whole thing as a B&amp;W. But thats just my taste so ignore me. Nice shot anyhow.</td>', 'personally I dont like the selective desaturation you''ve done here, I''d lke to see the whole thing as a B&W. But thats just my taste so ignore me. Nice shot anyhow.', '2004-04-17 10:09:37.000000', NULL, 1),
(672769, 69159, 15810, '<td valign="top">Brilliant photo, Lovely framing. Could submit for Silhouettes too! 10</td>', 'Brilliant photo, Lovely framing. Could submit for Silhouettes too! 10', '2004-04-17 10:10:41.000000', NULL, 1),
(672772, 69554, 15810, '<td valign="top">Really interesting, rather a lot going on for the eye to take in but I really like it....great work.</td>', 'Really interesting, rather a lot going on for the eye to take in but I really like it....great work.', '2004-04-17 10:11:31.000000', NULL, 1),
(672773, 69629, 15810, '<td valign="top">Nicely done...good work.</td>', 'Nicely done...good work.', '2004-04-17 10:13:05.000000', NULL, 1),
(672780, 68375, 14891, '<td valign="top">Critique Club Member:<br/>This photo was very nicely composed. The red on the fingers are somewhat intriguing and draws my attention to make me wonder if the subject is relaxing or in a struggle. The colors are very drab and create a somber mood. As with any "shower scene" we always come to think of the "Psycho" movies, perhaps this was the mood you were trying to create; and along with the "blood" have captured what you set out to do, if that was the case.<br/>All the proper qualities of a great photograph. If I had to point out one flaw that I could see I''d say that it was the bit of "gray area" that is near the fingers that sort of take away from a higher score. I liked it and voted an 8</td>', 'Critique Club Member:This photo was very nicely composed. The red on the fingers are somewhat intriguing and draws my attention to make me wonder if the subject is relaxing or in a struggle. The colors are very drab and create a somber mood. As with any "shower scene" we always come to think of the "Psycho" movies, perhaps this was the mood you were trying to create; and along with the "blood" have captured what you set out to do, if that was the case.All the proper qualities of a great photograph. If I had to point out one flaw that I could see I''d say that it was the bit of "gray area" that is near the fingers that sort of take away from a higher score. I liked it and voted an 8', '2004-04-17 10:35:41.000000', NULL, 1),
(672781, 69531, 14891, '<td valign="top">Solid 7</td>', 'Solid 7', '2004-04-17 10:38:23.000000', NULL, 1),
(672798, 69465, 3724, '<td valign="top">A very common view that everyone who drives can identify with, but done with beautiful  intutive technique resulting in superbe clarity and wonderful colour -  high score for this</td>', 'A very common view that everyone who drives can identify with, but done with beautiful  intutive technique resulting in superbe clarity and wonderful colour -  high score for this', '2004-04-17 11:03:23.000000', NULL, 1),
(672827, 68873, 16775, '<td valign="top">i think this title should have made reference to the effect that one of these was your "other", even if its just the neighbors. like "She Lied" or something would have made it a bit more of a gut wrencher.  :)</td>', 'i think this title should have made reference to the effect that one of these was your "other", even if its just the neighbors. like "She Lied" or something would have made it a bit more of a gut wrencher.  :)', '2004-04-17 11:25:57.000000', NULL, 1),
(672832, 69383, 19668, '<td valign="top">Looks like you dragged a window out into the wilderness...<br/>If the window frame had lay in shadows it would have been a bit more believable.</td>', 'Looks like you dragged a window out into the wilderness...If the window frame had lay in shadows it would have been a bit more believable.', '2004-04-17 11:36:47.000000', NULL, 1),
(672885, 69631, 12268, '<td valign="top">so, I''m sure you have gotten comments about this shot being underexposed, so I would add that, IMO, the challenge was to take a shot of a view from your window not the window per se. As such, I''m not sure how this fits the challenge (but I''m willing to hear your thoughts on this). As the title says, the suject is boring and there isn''t much to grab the viewer. I do like the border, however. It goes with the shot well.</td>', 'so, I''m sure you have gotten comments about this shot being underexposed, so I would add that, IMO, the challenge was to take a shot of a view from your window not the window per se. As such, I''m not sure how this fits the challenge (but I''m willing to hear your thoughts on this). As the title says, the suject is boring and there isn''t much to grab the viewer. I do like the border, however. It goes with the shot well.', '2004-04-17 12:29:26.000000', NULL, 1),
(672886, 69619, 12268, '<td valign="top">bery nice &amp; original. If it were not for the reflection, it would be hard to see how this was taken from the outside. I like that! Good stuff!</td>', 'bery nice & original. If it were not for the reflection, it would be hard to see how this was taken from the outside. I like that! Good stuff!', '2004-04-17 12:30:51.000000', NULL, 1),
(672888, 69488, 12268, '<td valign="top">very nice idea hear. I like it a lot. The only thing I would say to improve is to have a tighter crop and change the angle, which creates the slant that is slightly distracting to me.</td>', 'very nice idea hear. I like it a lot. The only thing I would say to improve is to have a tighter crop and change the angle, which creates the slant that is slightly distracting to me.', '2004-04-17 12:32:31.000000', NULL, 1),
(672892, 69259, 12268, '<td valign="top">This is an interesting shot. However, there seems to be some motion blur caused by camera shake. THe composition is nice but the afrementioned problem makes it hard to appreciate this.</td>', 'This is an interesting shot. However, there seems to be some motion blur caused by camera shake. THe composition is nice but the afrementioned problem makes it hard to appreciate this.', '2004-04-17 12:33:52.000000', NULL, 1),
(672895, 68967, 12268, '<td valign="top">nice idea here, I like the dualism of the inside &amp; outside window views.</td>', 'nice idea here, I like the dualism of the inside & outside window views.', '2004-04-17 12:35:01.000000', NULL, 1),
(672897, 69543, 12268, '<td valign="top">I like this shot a lot. original. I like the way the outside is out of focus but the view inside is in focus. Nice job here.</td>', 'I like this shot a lot. original. I like the way the outside is out of focus but the view inside is in focus. Nice job here.', '2004-04-17 12:36:27.000000', NULL, 1),
(672899, 69028, 12268, '<td valign="top">very nice window with a great view.</td>', 'very nice window with a great view.', '2004-04-17 12:37:48.000000', NULL, 1),
(672901, 69588, 12268, '<td valign="top">Very nice. this might have been slightly better in colour, IMO. Not scoring you low for it tho, jus tin case you were wondering.</td>', 'Very nice. this might have been slightly better in colour, IMO. Not scoring you low for it tho, jus tin case you were wondering.', '2004-04-17 12:39:20.000000', NULL, 1),
(672903, 69621, 12268, '<td valign="top">one of my faves thus far. Love the dual tones &amp; the DOF. You did a lot to make an ordinary view quite extraordinary!<br/> Good job!</td>', 'one of my faves thus far. Love the dual tones & the DOF. You did a lot to make an ordinary view quite extraordinary! Good job!', '2004-04-17 12:40:20.000000', NULL, 1),
(672909, 69611, 12268, '<td valign="top">very nice &amp; colourful! just one thing tho, the glare off the window on the right. not what you could have done to avoid it but it is the only thing I see that slightly takes away from the shot. 8</td>', 'very nice & colourful! just one thing tho, the glare off the window on the right. not what you could have done to avoid it but it is the only thing I see that slightly takes away from the shot. 8', '2004-04-17 12:49:13.000000', NULL, 1),
(672910, 69506, 12268, '<td valign="top">fantastic! 10</td>', 'fantastic! 10', '2004-04-17 12:49:38.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(673020, 68983, 2764, '<td valign="top">Lovely - it looks like a wedding, maybe the day afer when the excitement is over and it is time to reflect.  the light is really nice when it shines through the rose petals.  The colors are so soothiing.</td>', 'Lovely - it looks like a wedding, maybe the day afer when the excitement is over and it is time to reflect.  the light is really nice when it shines through the rose petals.  The colors are so soothiing.', '2004-04-17 15:29:02.000000', NULL, 1),
(673035, 69606, 17855, '<td valign="top">Cute dog.</td>', 'Cute dog.', '2004-04-17 15:57:07.000000', NULL, 1),
(673037, 69518, 17855, '<td valign="top">Very intense look in the dog''s eyes. Was it really raining?</td>', 'Very intense look in the dog''s eyes. Was it really raining?', '2004-04-17 15:58:05.000000', NULL, 1),
(673038, 68967, 17855, '<td valign="top">Nice</td>', 'Nice', '2004-04-17 16:00:13.000000', NULL, 1),
