(673042, 69256, 17855, '<td valign="top">Awesome. Love this:)</td>', 'Awesome. Love this:)', '2004-04-17 16:04:48.000000', NULL, 1),
(673044, 69539, 17855, '<td valign="top">Nice sky.</td>', 'Nice sky.', '2004-04-17 16:08:12.000000', NULL, 1),
(673074, 69132, 18709, '<td valign="top">This is a good picture, regardless of your religious persuasion.</td>', 'This is a good picture, regardless of your religious persuasion.', '2004-04-17 17:20:48.000000', NULL, 1),
(673076, 69312, 18709, '<td valign="top">A pretty good view, out to a misty horizon.  Why did this need to be validated.  It seems meet the challenge?</td>', 'A pretty good view, out to a misty horizon.  Why did this need to be validated.  It seems meet the challenge?', '2004-04-17 17:26:08.000000', NULL, 1),
(673078, 69646, 18709, '<td valign="top">Very vivid colours.  But they seem to b e alright.  Just very bright light.</td>', 'Very vivid colours.  But they seem to b e alright.  Just very bright light.', '2004-04-17 17:27:39.000000', NULL, 1),
(673079, 69319, 18709, '<td valign="top">Nicely taken.  There is a reproachful look in the cats eyes.  I hope he/she got fed.</td>', 'Nicely taken.  There is a reproachful look in the cats eyes.  I hope he/she got fed.', '2004-04-17 17:28:41.000000', NULL, 1),
(673081, 69525, 18709, '<td valign="top">A nicely fragmented picture.   Slightly abstract.  Conveys the cold.</td>', 'A nicely fragmented picture.   Slightly abstract.  Conveys the cold.', '2004-04-17 17:29:52.000000', NULL, 1),
(673082, 69488, 18709, '<td valign="top">This is well-taken.</td>', 'This is well-taken.', '2004-04-17 17:31:02.000000', NULL, 1),
(673085, 69652, 18709, '<td valign="top">Too many days like this. But I don''t think it makes a good picture.</td>', 'Too many days like this. But I don''t think it makes a good picture.', '2004-04-17 17:31:55.000000', NULL, 1),
(673088, 69674, 18709, '<td valign="top">Just a bit too depressing.  We see a hint of the variety of colour outside, but that is all.</td>', 'Just a bit too depressing.  We see a hint of the variety of colour outside, but that is all.', '2004-04-17 17:33:27.000000', NULL, 1),
(673090, 69487, 18709, '<td valign="top">A very sweet picture.   Finely focussed.</td>', 'A very sweet picture.   Finely focussed.', '2004-04-17 17:34:26.000000', NULL, 1),
(673091, 69641, 18709, '<td valign="top">A bit of a moonscape this.  Grainy, like an old newpaper picture.  Is that the intention?</td>', 'A bit of a moonscape this.  Grainy, like an old newpaper picture.  Is that the intention?', '2004-04-17 17:35:53.000000', NULL, 1),
(673092, 68397, 18709, '<td valign="top">Poor chap.  Hasn''t got much choice. the outside looks as bleak as the inside.</td>', 'Poor chap.  Hasn''t got much choice. the outside looks as bleak as the inside.', '2004-04-17 17:37:03.000000', NULL, 1),
(673095, 69578, 18709, '<td valign="top">There must have been better views than this.  Presumably the train is statioinary at the signals, but even a blurred ''moving''  picture might have been more interesting.</td>', 'There must have been better views than this.  Presumably the train is statioinary at the signals, but even a blurred ''moving''  picture might have been more interesting.', '2004-04-17 17:39:16.000000', NULL, 1),
(673096, 69578, 16862, '<td valign="top">A good photo, just too much of a snapshot fo my taste</td>', 'A good photo, just too much of a snapshot fo my taste', '2004-04-17 17:39:22.000000', NULL, 1),
(673097, 69506, 18709, '<td valign="top">I suppose it looks the same on weekdays, but YOU feel different.   Well taken.<br/><br/><i>Message edited by author 2004-04-19 08:10:15.</i></td>', 'I suppose it looks the same on weekdays, but YOU feel different.   Well taken.', '2004-04-17 17:40:21.000000', '2004-04-19 09:10:15.000000', 1),
(673099, 69134, 18709, '<td valign="top">I take it that this was shot through the aperture in a ruined wall.  I suppose if it was a window once, it still is.  Nicely framed.</td>', 'I take it that this was shot through the aperture in a ruined wall.  I suppose if it was a window once, it still is.  Nicely framed.', '2004-04-17 17:42:03.000000', NULL, 1),
(673100, 69678, 16862, '<td valign="top">A beautiful frame but I feel the window is too closed, I  would like to see the trees and the person better. Just something is´t working  a 6</td>', 'A beautiful frame but I feel the window is too closed, I  would like to see the trees and the person better. Just something is´t working  a 6', '2004-04-17 17:42:12.000000', NULL, 1),
(673101, 69161, 18709, '<td valign="top">Well, who said the windows have to be intact?</td>', 'Well, who said the windows have to be intact?', '2004-04-17 17:43:06.000000', NULL, 1),
(673102, 69606, 16862, '<td valign="top">A funny shot, but I hardly get the feeling of a window</td>', 'A funny shot, but I hardly get the feeling of a window', '2004-04-17 17:43:16.000000', NULL, 1),
(673103, 69540, 18709, '<td valign="top">This looks a bit forbidding.  Just the right amount of light.  To me it seems to lean slightly to the right, but it might just be the perspective.</td>', 'This looks a bit forbidding.  Just the right amount of light.  To me it seems to lean slightly to the right, but it might just be the perspective.', '2004-04-17 17:45:05.000000', NULL, 1),
(673104, 69631, 16862, '<td valign="top">Just isn´t stylish like it´s probably supposed to be.</td>', 'Just isn´t stylish like it´s probably supposed to be.', '2004-04-17 17:45:16.000000', NULL, 1),
(673105, 69556, 18709, '<td valign="top">I usually prefer B/W,  but on this occasion, I think colour would have enhanced the image. It is very good anyway.  Just my opinion.</td>', 'I usually prefer B/W,  but on this occasion, I think colour would have enhanced the image. It is very good anyway.  Just my opinion.', '2004-04-17 17:46:36.000000', NULL, 1),
(673106, 68551, 16862, '<td valign="top">A good shot. But maybe it should have shown the window it self to get a little frame, The spot in top left corner really spoils everything</td>', 'A good shot. But maybe it should have shown the window it self to get a little frame, The spot in top left corner really spoils everything', '2004-04-17 17:47:49.000000', NULL, 1),
(673108, 69671, 18709, '<td valign="top">I hope you didn''t take your hands off the wheel.   God shot. The dials in sharp focus, and the distant hills slight ''blued''</td>', 'I hope you didn''t take your hands off the wheel.   God shot. The dials in sharp focus, and the distant hills slight ''blued''', '2004-04-17 17:48:14.000000', NULL, 1),
(673109, 69535, 16862, '<td valign="top">I really really like this one, A lot of style</td>', 'I really really like this one, A lot of style', '2004-04-17 17:49:00.000000', NULL, 1),
(673110, 69386, 18709, '<td valign="top">Perhaps this squirrel is a showman.   He seems quite unconcerned.  A good shot.</td>', 'Perhaps this squirrel is a showman.   He seems quite unconcerned.  A good shot.', '2004-04-17 17:49:23.000000', NULL, 1),
(673111, 69582, 16862, '<td valign="top">The interior spoils it</td>', 'The interior spoils it', '2004-04-17 17:49:34.000000', NULL, 1),
(673112, 69028, 16862, '<td valign="top">Ísland gamla Ísland</td>', 'Ísland gamla Ísland', '2004-04-17 17:50:35.000000', NULL, 1),
(673113, 69678, 18709, '<td valign="top">I like this.  The old wooden window-frame and shutters look authentic and the restricted view outside is just right.</td>', 'I like this.  The old wooden window-frame and shutters look authentic and the restricted view outside is just right.', '2004-04-17 17:50:52.000000', NULL, 1),
(673114, 69505, 16862, '<td valign="top">Could have been a lot better, a good idea</td>', 'Could have been a lot better, a good idea', '2004-04-17 17:51:07.000000', NULL, 1),
(673116, 69390, 16862, '<td valign="top">Like it</td>', 'Like it', '2004-04-17 17:51:45.000000', NULL, 1),
(673117, 69499, 16862, '<td valign="top">Too centered</td>', 'Too centered', '2004-04-17 17:52:06.000000', NULL, 1),
(673119, 69028, 18709, '<td valign="top">Very good.  The shapes complement each other.  Would that be a slag heap. it just looks too symmetrical to be natural.</td>', 'Very good.  The shapes complement each other.  Would that be a slag heap. it just looks too symmetrical to be natural.', '2004-04-17 17:53:05.000000', NULL, 1),
(673120, 69550, 11793, '<td valign="top">bit of noise in the sky, nice photo though.<br/> <br/>good luck</td>', 'bit of noise in the sky, nice photo though. good luck', '2004-04-17 17:54:03.000000', NULL, 1),
(673121, 68785, 16862, '<td valign="top">A real artwork, but too much digital art for my taste.</td>', 'A real artwork, but too much digital art for my taste.', '2004-04-17 17:54:43.000000', NULL, 1),
(673122, 69618, 16862, '<td valign="top">A really beautiful picture   a winner</td>', 'A really beautiful picture   a winner', '2004-04-17 17:55:34.000000', NULL, 1),
(673123, 69308, 16862, '<td valign="top">A good shot  but too blurry</td>', 'A good shot  but too blurry', '2004-04-17 17:56:29.000000', NULL, 1),
(673124, 69648, 18709, '<td valign="top">I think this would have looked better if you had taken it a fraction of a second earlier, and the subject was a bit further back, with more room in the picture to go forward, if you know what I mean. At the moment he looks as if he is walking ''out'' of the frame.  A moving object usually looks better if there is more space in front of him than behind.</td>', 'I think this would have looked better if you had taken it a fraction of a second earlier, and the subject was a bit further back, with more room in the picture to go forward, if you know what I mean. At the moment he looks as if he is walking ''out'' of the frame.  A moving object usually looks better if there is more space in front of him than behind.', '2004-04-17 17:56:42.000000', NULL, 1),
(673125, 69308, 18709, '<td valign="top">There is quite an atmosphere about this picture. It is very well-taken.</td>', 'There is quite an atmosphere about this picture. It is very well-taken.', '2004-04-17 17:58:49.000000', NULL, 1),
(673126, 69111, 16862, '<td valign="top">I like this one  Flott mynd</td>', 'I like this one  Flott mynd', '2004-04-17 17:59:48.000000', NULL, 1),
(673127, 69506, 6405, '<td valign="top">is this Bobster?,cool photo,8 !</td>', 'is this Bobster?,cool photo,8 !', '2004-04-17 18:00:05.000000', NULL, 1),
(673130, 69259, 16862, '<td valign="top">Out of focus,</td>', 'Out of focus,', '2004-04-17 18:01:43.000000', NULL, 1),
